def transform(grid):
    # The 6s divide the grid into 4x3 tiles. Mark a tile with 1 when it
    # contains at least two marker cells; otherwise use the background color.
    rows = [r for r in range(len(grid)) if any(v != 6 for v in grid[r])]
    cols = [c for c in range(len(grid[0])) if any(grid[r][c] != 6 for r in range(len(grid)))]
    # Split at separator lines.
    row_groups = []
    start = 0
    for r in range(len(grid)):
        if all(v == 6 for v in grid[r]):
            if start < r:
                row_groups.append(range(start, r))
            start = r + 1
    if start < len(grid):
        row_groups.append(range(start, len(grid)))

    col_groups = []
    start = 0
    for c in range(len(grid[0])):
        if all(grid[r][c] == 6 for r in range(len(grid))):
            if start < c:
                col_groups.append(range(start, c))
            start = c + 1
    if start < len(grid[0]):
        col_groups.append(range(start, len(grid[0])))

    marker = next(v for row in grid for v in row if v not in (4, 6))
    background = next(v for row in grid for v in row if v not in (6, marker))
    return [[1 if sum(grid[r][c] == marker for r in rg for c in cg) >= 2 else background
             for cg in col_groups] for rg in row_groups]
